<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,reactive,ref,watch} from 'vue';
import {amountCents,decimal,money} from './tradeAmounts';
type Item={id:string;[key:string]:any};
type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
const props=withDefaults(defineProps<{request:Request;readonly:boolean;access:{contracts:{read:boolean;write:boolean};receiptRead?:boolean};customerWrite:boolean;customerId?:string}>(),{customerId:''});
const emit=defineEmits<{customer:[id:string];contract:[id:string];clearFilter:[]}>();
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const busy=ref(false),error=ref(''),success=ref(''),items=ref<Item[]>([]),total=ref(0),page=ref(1),q=ref(''),state=ref('');
const balances=ref<Item|null>(null);
const dialog=ref(''),modal=ref<HTMLElement|null>(null),selected=ref<Item|null>(null),history=ref<Item[]>([]),quotes=ref<Item[]>([]),quoteTotal=ref(0),quotePage=ref(1),quoteQuery=ref(''),requestKey=ref('');
const form=reactive({quoteId:'',quoteExpectedVersion:0,title:'',expectedDeliveryDate:'',notes:'',reason:'',startDate:today,endDate:today.slice(0,4)+'-12-31',planDate:today.slice(0,4)+'-12-31'});
const delivery=ref<{lineId:string;quantity:string}[]>([]);
const states:Record<string,string>={DRAFT:'草稿',CONFIRMED:'已确认',IN_DELIVERY:'部分履约',DELIVERED:'已履约',VOID:'已作废'};
const actions:Record<string,string>={CREATED:'创建订单',UPDATED:'修改草稿',CONFIRM:'确认订单',VOID:'作废订单',FULFILLMENT:'登记履约'};
const canCreate=computed(()=>!props.readonly&&props.access.contracts.write&&props.customerWrite);
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn();}catch(e){const f=e as Error&{status?:number};error.value=f.message||'操作未完成';if([401,403,404].includes(f.status??0)){dialog.value='';selected.value=null;items.value=[];}}finally{busy.value=false;}}
async function load(){const r=await props.request<{items:Item[];total:number}>(`/sales-orders?page=${page.value}&pageSize=20&q=${encodeURIComponent(q.value)}&status=${state.value}${props.customerId?'&customerId='+props.customerId:''}`);items.value=r.items;total.value=r.total;}
function search(){page.value=1;run(load);}function turn(d:number){page.value+=d;run(load);}
async function options(){const r=await props.request<{items:Item[];total:number}>(`/sales-orders/quote-options?page=${quotePage.value}&pageSize=20&q=${encodeURIComponent(quoteQuery.value)}${props.customerId?'&customerId='+props.customerId:''}`);quotes.value=r.items;quoteTotal.value=r.total;}
function openCreate(){run(async()=>{selected.value=null;Object.assign(form,{quoteId:'',quoteExpectedVersion:0,title:'',expectedDeliveryDate:'',notes:'',reason:''});quotePage.value=1;quoteQuery.value='';requestKey.value=crypto.randomUUID();await options();dialog.value='edit';});}
function selectQuote(){const choice=quotes.value.find(x=>x.id===form.quoteId);if(choice){form.quoteExpectedVersion=choice.version;form.title=choice.title;}}
async function detail(id:string){selected.value=await props.request<Item>('/sales-orders/'+id);balances.value=selected.value.contractId&&props.access.receiptRead?await props.request<Item>('/finance/orders/'+id+'/balances'):null;const r=await props.request<{items:Item[]}>(`/sales-orders/${id}/history?page=1&pageSize=50`);history.value=r.items;dialog.value='view';}
function show(item:Item){run(()=>detail(item.id));}
function edit(){if(!selected.value)return;Object.assign(form,{title:selected.value.title,expectedDeliveryDate:selected.value.expectedDeliveryDate??'',notes:selected.value.notes});dialog.value='edit';}
function save(){run(async()=>{let id=selected.value?.id;if(id)await props.request('/sales-orders/'+id,'PUT',{title:form.title,expectedDeliveryDate:form.expectedDeliveryDate||null,notes:form.notes,expectedVersion:selected.value!.version});else{if(!form.quoteId)throw new Error('请选择已批准报价');const order=await props.request<Item>('/sales-orders','POST',{quoteId:form.quoteId,quoteExpectedVersion:form.quoteExpectedVersion,title:form.title,expectedDeliveryDate:form.expectedDeliveryDate||null,notes:form.notes},{'Idempotency-Key':requestKey.value});id=order.id;}await load();await detail(id!);success.value='订单草稿已保存';});}
function decide(action:'confirm'|'void'){if(!selected.value)return;form.reason='';requestKey.value=crypto.randomUUID();dialog.value=action;}
function applyDecision(){run(async()=>{const action=dialog.value;const old=selected.value!;const r=await props.request<Item>(`/sales-orders/${old.id}/${action}`,'POST',{expectedVersion:old.version,reason:form.reason},{'Idempotency-Key':requestKey.value});await load();await detail(r.id);success.value=action==='confirm'?'订单已确认，现可建立合同与登记履约':'订单已作废，历史保留';});}
function openDelivery(){if(!selected.value)return;delivery.value=selected.value.lines.map((l:Item)=>({lineId:l.id,quantity:String(l.deliveredQuantity)}));dialog.value='delivery';}
function saveDelivery(){run(async()=>{const old=selected.value!;const lines=delivery.value.map(l=>({lineId:l.lineId,deliveredQuantity:l.quantity}));const r=await props.request<Item>(`/sales-orders/${old.id}/fulfillment`,'PUT',{expectedVersion:old.version,lines});await load();await detail(r.id);success.value='履约数量已保存';});}
function openContract(){if(!selected.value)return;Object.assign(form,{title:selected.value.title,startDate:today,endDate:today.slice(0,4)+'-12-31',planDate:today.slice(0,4)+'-12-31',notes:''});requestKey.value=crypto.randomUUID();dialog.value='contract';}
function createContract(){run(async()=>{const o=selected.value!;const r=await props.request<Item>('/contracts','POST',{orderId:o.id,quoteId:o.quoteId,quoteExpectedVersion:o.quoteVersion,title:form.title,startDate:form.startDate,endDate:form.endDate,notes:form.notes,plans:[{title:'合同款',amountCents:amountCents(decimal(o.totalCents)),dueDate:form.planDate}]},{'Idempotency-Key':requestKey.value});await load();await detail(o.id);success.value=`合同 ${r.contractNumber} 已创建，分期计划可在合同管理调整`;});}
let prior:HTMLElement|null=null,overflow='';watch(dialog,async(v,old)=>{if(v&&!old){prior=document.activeElement as HTMLElement;overflow=document.body.style.overflow;document.body.style.overflow='hidden';}if(v){await nextTick();modal.value?.querySelector<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled)')?.focus({preventScroll:true});}else{document.body.style.overflow=overflow;prior?.focus({preventScroll:true});}});
function keys(e:KeyboardEvent){if(!dialog.value)return;if(e.key==='Escape'&&!busy.value)dialog.value='';if(e.key==='Tab'){const nodes=modal.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
onMounted(()=>{document.addEventListener('keydown',keys);run(load);});onUnmounted(()=>{document.removeEventListener('keydown',keys);if(dialog.value)document.body.style.overflow=overflow;});
</script>
<template>
 <section class="order-workspace"><div class="page-heading"><div><span class="eyebrow">SALES ORDERS</span><h1>销售订单</h1><p>批准报价转订单，确认后建立合同，按明细记录履约数量。</p></div><div class="order-actions"><button class="btn secondary" :disabled="busy" @click="run(load)">刷新</button><button v-if="canCreate" class="btn primary" :disabled="busy" @click="openCreate">从批准报价建订单</button></div></div>
 <p v-if="customerId" class="order-note">正在查看指定客户的订单。<button class="text-button" @click="emit('clearFilter')">查看全部</button></p><p v-if="readonly" class="order-note">当前企业仅允许查看资料。</p><p v-if="error&&!dialog" class="order-alert error" role="alert">{{error}}</p><p v-if="success" class="order-alert ok" role="status">{{success}}</p>
 <form class="card order-filters" @submit.prevent="search"><label>搜索<input v-model="q" maxlength="100" placeholder="订单编号、主题或客户"/></label><label>状态<select v-model="state"><option value="">全部状态</option><option v-for="(label,key) in states" :key="key" :value="key">{{label}}</option></select></label><button class="btn secondary" :disabled="busy">查询</button></form>
 <div class="card order-table"><div class="table-scroll"><table><thead><tr><th>订单</th><th>客户</th><th>状态</th><th>含税金额</th><th>预计交付</th><th>合同</th><th>操作</th></tr></thead><tbody><tr v-for="r in items" :key="r.id"><td><strong>{{r.orderNumber}}</strong><small>{{r.title}}</small></td><td><button class="text-button" @click="emit('customer',r.customerId)">{{r.customerNameSnapshot}}</button></td><td><span class="badge neutral">{{states[r.status]}}</span></td><td>{{money(r.totalCents)}}</td><td>{{r.expectedDeliveryDate||'—'}}</td><td>{{r.contractId?'已关联':'—'}}</td><td><button class="text-button" :disabled="busy" @click="show(r)">查看 / 处理</button></td></tr></tbody></table></div><p v-if="!items.length" class="order-empty">{{busy?'正在读取…':'当前筛选下没有销售订单'}}</p><div class="order-pages"><span>共 {{total}} 条 · 第 {{page}} 页</span><button class="btn secondary" :disabled="busy||page===1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="busy||page*20>=total" @click="turn(1)">下一页</button></div></div>
 <Teleport to="body"><div v-if="dialog" class="order-backdrop" @click.self="!busy&&(dialog='')"><section ref="modal" class="order-dialog" role="dialog" aria-modal="true" aria-labelledby="order-dialog-title"><header><h2 id="order-dialog-title">{{dialog==='edit'?(selected?'编辑订单草稿':'从批准报价建订单'):dialog==='view'?'销售订单详情':dialog==='contract'?'从订单建立合同':dialog==='delivery'?'登记履约':dialog==='confirm'?'确认订单':'作废订单'}}</h2><button type="button" class="btn secondary" :disabled="busy" @click="dialog=''">关闭</button></header>
 <div class="order-body"><p v-if="error" class="order-alert error" role="alert">{{error}}</p><template v-if="dialog==='view'&&selected"><div class="order-summary"><div><span>编号 / 状态</span><strong>{{selected.orderNumber}} · {{states[selected.status]}}</strong></div><div><span>客户 / 负责人</span><strong>{{selected.customerNameSnapshot}} · {{selected.ownerNameSnapshot}}</strong></div><div><span>订单含税金额</span><strong>{{money(selected.totalCents)}}</strong></div><div v-if="selected.estimatedCostCents!=null"><span>成本估算 / 预计毛利</span><strong>{{money(selected.estimatedCostCents)}} / {{((selected.totalCents-selected.estimatedCostCents)/selected.totalCents*100).toFixed(1)}}%</strong></div><div><span>批准报价 / 交付日期</span><strong>v{{selected.quoteVersion}} · {{selected.expectedDeliveryDate||'未设定'}}</strong></div><div><span>关联合同</span><button v-if="selected.contractId" class="text-button" @click="emit('contract',selected.contractId);dialog=''">打开合同详情</button><strong v-else>尚未建立</strong></div></div><div v-if="balances" class="order-summary"><div><span>净已开票 / 未开票</span><strong>{{money(balances.invoicedCents)}} / {{money(balances.uninvoicedCents)}}</strong></div><div><span>净已到账 / 未到账</span><strong>{{money(balances.receivedCents)}} / {{money(balances.unreceivedCents)}}</strong></div></div><p>{{selected.notes||'无备注'}}</p><div v-if="!readonly&&selected.canManage" class="order-actions"><button v-if="selected.status==='DRAFT'" class="btn secondary" @click="edit">编辑草稿</button><button v-if="selected.status==='DRAFT'" class="btn primary" @click="decide('confirm')">确认订单</button><button v-if="['DRAFT','CONFIRMED'].includes(selected.status)&&!selected.contractId" class="btn secondary" @click="decide('void')">作废</button><button v-if="['CONFIRMED','IN_DELIVERY','DELIVERED'].includes(selected.status)&&!selected.contractId" class="btn primary" @click="openContract">建立合同</button><button v-if="['CONFIRMED','IN_DELIVERY','DELIVERED'].includes(selected.status)" class="btn secondary" @click="openDelivery">登记履约</button></div><div class="order-block"><h3>产品／服务明细</h3><div class="table-scroll"><table><thead><tr><th>产品</th><th>数量</th><th>已履约</th><th>折扣</th><th>含税金额</th></tr></thead><tbody><tr v-for="l in selected.lines" :key="l.id"><td>{{l.skuSnapshot}} · {{l.nameSnapshot}}</td><td>{{l.quantity}} {{l.unitSnapshot}}</td><td>{{l.deliveredQuantity}} {{l.unitSnapshot}}</td><td>{{(l.discountBps/100).toFixed(1)}}%</td><td>{{money(l.amountCents)}}</td></tr></tbody></table></div></div><div class="order-block"><h3>操作记录</h3><div v-for="h in history" :key="h.businessVersion" class="order-event">v{{h.businessVersion}} · {{actions[h.action]||h.action}} · {{h.actorNameSnapshot}} <span>{{h.createdAt}}</span><small v-if="h.reason">{{h.reason}}</small></div></div></template>
 <form v-else class="order-form" @submit.prevent="dialog==='edit'?save():dialog==='delivery'?saveDelivery():dialog==='contract'?createContract():applyDecision()"><fieldset :disabled="busy||readonly"><template v-if="dialog==='edit'"><div v-if="!selected" class="order-block"><h3>选择未转换的有效批准报价</h3><div class="order-actions"><input v-model="quoteQuery" maxlength="100" placeholder="报价编号或主题"/><button type="button" class="btn secondary" @click="run(async()=>{quotePage=1;await options()})">搜索</button></div><select v-model="form.quoteId" required @change="selectQuote"><option value="">选择报价</option><option v-for="item in quotes" :key="item.id" :value="item.id">{{item.quoteNumber}} · {{item.customerNameSnapshot}} · {{money(item.totalCents)}}</option></select><div class="order-pages"><span>共 {{quoteTotal }} 条</span><button type="button" class="text-button" :disabled="quotePage===1" @click="run(async()=>{quotePage--;await options()})">上一页</button><button type="button" class="text-button" :disabled="quotePage*20>=quoteTotal" @click="run(async()=>{quotePage++;await options()})">下一页</button></div></div><label>订单主题<input v-model="form.title" required maxlength="200"/></label><label>预计交付日期<input v-model="form.expectedDeliveryDate" type="date" min="2000-01-01" max="2100-12-31"/></label><label>备注<textarea v-model="form.notes" maxlength="4000" rows="3"/></label><p class="order-note">金额及行项目由已批准报价生成；订单确认后不可直接修改商业明细。</p></template>
 <template v-else-if="dialog==='delivery'"><p class="order-note">填写每行累计已履约数量，不得减少或超过订单数量。状态会随明细自动更新。</p><div v-for="(l,i) in selected?.lines??[]" :key="l.id" class="order-delivery"><span>{{l.nameSnapshot}} · {{l.quantity}} {{l.unitSnapshot}}</span><label>累计已履约<input v-model="delivery[Number(i)].quantity" type="number" min="0" :max="l.quantity" step="0.0001" required/></label></div></template>
 <template v-else-if="dialog==='contract'"><p class="order-note">合同金额 {{money(selected?.totalCents)}}，自动生成一期收款计划。合同草稿里可调整期次，但总额必须保持一致。</p><label>合同主题<input v-model="form.title" maxlength="200" required/></label><div class="order-grid"><label>开始日期<input v-model="form.startDate" type="date" min="2000-01-01" max="2100-12-31" required/></label><label>结束日期<input v-model="form.endDate" type="date" min="2000-01-01" max="2100-12-31" required/></label><label>该期应收日期<input v-model="form.planDate" type="date" min="2000-01-01" max="2100-12-31" required/></label></div><label>备注<textarea v-model="form.notes" rows="3" maxlength="4000"/></label></template>
 <template v-else><p>{{selected?.orderNumber}} · {{selected?.title}}</p><p class="order-note">{{dialog==='confirm'?'再次校验报价审批、折扣与毛利规则后确认。':'作废会保留订单及操作历史，已关联的合同或履约不能作废。'}}</p><label v-if="dialog==='void'">作废原因<textarea v-model="form.reason" rows="3" maxlength="500" required/></label></template></fieldset><footer><button type="button" class="btn secondary" @click="dialog=selected?'view':''">返回</button><button class="btn primary" :disabled="busy||readonly">{{busy?'处理中…':'确认保存'}}</button></footer></form></div></section></div></Teleport>
 </section>
</template>
<style scoped>
.order-workspace{min-width:0}.order-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.order-filters{padding:18px;margin:20px 0;display:flex;align-items:end;gap:14px;flex-wrap:wrap}.order-filters label:first-child{flex:1;min-width:230px}.order-workspace label,.order-dialog label{display:flex;flex-direction:column;gap:7px;font-size:13px}.order-workspace input,.order-workspace select,.order-dialog input,.order-dialog select,.order-dialog textarea{width:100%;min-width:0;border:1px solid #7288a766;border-radius:9px;background:#142039;color:#eaf3ff;padding:10px;font:inherit}.order-table{overflow:hidden}.order-table small{display:block;color:#9aaac0;font-size:12px;margin-top:5px}.order-pages{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:15px}.order-pages span{margin-right:auto}.order-empty{text-align:center;padding:35px;color:#9aaac0}.order-note{color:#aab9cf;font-size:13px;line-height:1.7}.order-alert{padding:12px 14px;border-radius:9px;overflow-wrap:anywhere}.order-alert.error{background:#56283d;color:#ffe0e4}.order-alert.ok{background:#194a42;color:#c8fff1}.order-backdrop{position:fixed;inset:0;z-index:10000;background:#030919c9;display:flex;align-items:center;justify-content:center;padding:20px}.order-dialog{width:min(980px,100%);max-height:calc(100dvh - 40px);display:flex;flex-direction:column;overflow:hidden;color:#eaf3ff;background:linear-gradient(145deg,#1b2b47f5,#111a31f9);border:1px solid #7797c35a;border-radius:15px;box-shadow:0 25px 80px #0009}.order-dialog header{padding:18px 22px;border-bottom:1px solid #7b9dc43a;display:flex;align-items:center;justify-content:space-between;gap:12px}.order-dialog h2{font-size:20px}.order-body{padding:22px;overflow-y:auto;min-height:0;overscroll-behavior:contain}.order-form{display:grid;gap:17px}.order-form fieldset{padding:0;border:0;display:grid;gap:15px;min-width:0}.order-form footer{display:flex;justify-content:flex-end;gap:10px;border-top:1px solid #7b9dc43a;padding-top:16px}.order-grid,.order-summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.order-summary{background:#2032519a;border-radius:10px;padding:18px}.order-summary span,.order-summary strong{display:block;overflow-wrap:anywhere}.order-summary span,.order-event span{font-size:12px;color:#9eafc5}.order-block{padding:16px;border:1px solid #829dc643;border-radius:10px;margin:18px 0}.order-block h3{margin:0 0 12px;font-size:15px}.order-block table{width:100%;border-collapse:collapse}.order-block th,.order-block td{padding:10px;text-align:left;border-bottom:1px solid #7896bf36}.order-event{border-bottom:1px solid #7896bf36;padding:9px 0}.order-event small{display:block}.order-delivery{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:10px 0;border-bottom:1px solid #7896bf36}.order-delivery label{width:min(190px,45%)}@media(max-width:650px){.order-backdrop{padding:10px}.order-dialog{max-height:calc(100dvh - 20px)}.order-body{padding:15px}.order-grid,.order-summary{grid-template-columns:1fr}.order-delivery{display:block}.order-delivery label{width:100%}}
</style>
